    speeds = {}
    for v in (0, 5, -1, 'fast', True, 1.0, 0.9):
        try:
            speeds[repr(v)] = validate_speed(v)
        except ValueError as exc:
            speeds[repr(v)] = 'refused'
    words = [{'word': 'مرحبا', 'start': 0.12, 'end': 0.58}, {'word': 'بكم', 'start': 0.66, 'end': 0.98}]
    caps = [{'t': w['start'], 'end': w['end'], 'text': w['word']} for w in words] if cases['heygen']['word_timestamps'] else None
    rep = jw(wd / 'tts_route.json', {'cases': cases, 'speeds': speeds, 'captions_from_response': caps})
    return ([check('HeyGen first when its key is set (timestamps in the response)', cases['heygen'] == {'provider': 'heygen-starfish', 'word_timestamps': True, 'needs_transcription': False}, cases['heygen'], 'heygen-starfish'), check('then ElevenLabs (no timestamps -> transcription needed), then local Kokoro', cases['eleven']['provider'] == 'elevenlabs' and cases['eleven']['needs_transcription'] and (cases['local']['provider'] == 'kokoro-82m'), [cases['eleven']['provider'], cases['local']['provider']], ['elevenlabs', 'kokoro-82m']), check('speed 0, 5, -1, text and a bool are refused before any TTS runs', all((speeds[x] == 'refused' for x in ('0', '5', '-1', "'fast'", 'True'))), speeds, 'refused'), check('valid speeds pass through (1.0, 0.9)', speeds['1.0'] == 1.0 and speeds['0.9'] == 0.9, [speeds['1.0'], speeds['0.9']], [1.0, 0.9]), check('captions built straight from response timestamps', caps and caps[0] == {'t': 0.12, 'end': 0.58, 'text': 'مرحبا'}, caps, 'from response'), check('negative control: no key and no model -> no provider, with the exact names to set', cases['none']['provider'] is None and 'HEYGEN_API_KEY' in cases['none']['reason'], cases['none'], 'None')], [rep])

